CREATE TABLE subjects (
    id        TEXT PRIMARY KEY,
    scope     TEXT NOT NULL DEFAULT 'default',
    name      TEXT NOT NULL,
    norm_name TEXT NOT NULL,
    type      TEXT NOT NULL CHECK (type IN ('entity', 'event', 'concept')),
    UNIQUE (scope, norm_name)
);

CREATE INDEX subjects_name_id ON subjects (name, id);

CREATE TABLE claims (
    id         TEXT PRIMARY KEY,
    subject_id TEXT NOT NULL,
