CREATE TABLE aliases (
    scope       TEXT NOT NULL DEFAULT 'default',
    norm_name   TEXT NOT NULL,
    subject_id  TEXT NOT NULL REFERENCES subjects(id) ON DELETE RESTRICT,
    name        TEXT NOT NULL,
    owner_id    TEXT NOT NULL,
    owner_email TEXT NOT NULL,
    created_at  TEXT NOT NULL,
    UNIQUE (scope, norm_name)
);

CREATE INDEX aliases_subject ON aliases (subject_id);

CREATE TABLE subject_merges (
    job_id          TEXT PRIMARY KEY REFERENCES jobs(id) ON DELETE CASCADE,
    from_subject_id TEXT NOT NULL,
    to_subject_id   TEXT NOT NULL,
    CHECK (from_subject_id <> to_subject_id)
);

CREATE INDEX subject_merges_from_to ON subject_merges (from_subject_id, to_subject_id);

CREATE TRIGGER subjects_restrict_claims_before_delete
BEFORE DELETE ON subjects
WHEN EXISTS (SELECT 1 FROM claims WHERE subject_id = OLD.id)
BEGIN
    SELECT RAISE(ABORT, 'subject has claims');
END;
